    std::vector<int> cantidades{0, 8, 15, 64};
    for (int cantidad : cantidades) {
        std::cout << "dec=" << std::dec << cantidad
            << ";hex=" << std::hex << cantidad << ";oct=" << std::oct << cantidad << "\n";
    }
    return 0;
}

